```

### Length Conversions

```xiom
fn convert_length(value: Float64, from: Str, to: Str) -> Float64 {
  let meters = to_meters(value, from);
  from_meters(meters, to)
}

fn to_meters(value: Float64, unit: Str) -> Float64 {
  if unit == "km" { return value * 1000.0; };
  if unit == "m" { return value; };
  if unit == "cm" { return value * 0.01; };
  if unit == "mm" { return value * 0.001; };
  if unit == "mile" { return value * 1609.34; };
  if unit == "ft" { return value * 0.3048; };
  if unit == "in" { return value * 0.0254; };
  value
}

fn from_meters(meters: Float64, unit: Str) -> Float64 {
  if unit == "km" { return meters / 1000.0; };
  if unit == "m" { return meters; };
  if unit == "cm" { return meters / 0.01; };
  if unit == "mm" { return meters / 0.001; };
  if unit == "mile" { return meters / 1609.34; };
  if unit == "ft" { return meters / 0.3048; };
  if unit == "in" { return meters / 0.0254; };
  meters
}
```

### Temperature (Special Case)

Temperature doesn't use simple multiplication — it uses formulas:

```xiom
fn convert_temperature(value: Float64, from: Str, to: Str) -> Float64 {
  let celsius = to_celsius(value, from);
  from_celsius(celsius, to)
}

fn to_celsius(value: Float64, unit: Str) -> Float64 {
  if unit == "C" { return value; };
  if unit == "F" { return (value - 32.0) * 5.0 / 9.0; };
  if unit == "K" { return value - 273.15; };
  value
}

fn from_celsius(celsius: Float64, unit: Str) -> Float64 {
  if unit == "C" { return celsius; };
  if unit == "F" { return celsius * 9.0 / 5.0 + 32.0; };
  if unit == "K" { return celsius + 273.15; };
  celsius
}
```

### Generalized Convert

```xiom
fn convert(value: Float64, from: Str, to: Str, category: Int) -> Float64 {
  if category == 0 { return convert_length(value as Int, from, to) as Float64; };
  if category == 2 { return convert_temperature(value, from, to); };
  value
}
```

