fn to_meters(value: Int, unit: Int) -> Int {
  if unit == 0 { return value; };
  if unit == 1 { return value * 1000; };
  if unit == 2 { return value / 100; };
  value
}

fn from_meters(meters: Int, unit: Int) -> Int {
  if unit == 0 { return meters; };
  if unit == 1 { return meters / 1000; };
  if unit == 2 { return meters * 100; };
  meters
}

fn convert_length(value: Int, from_unit: Int, to_unit: Int) -> Int {
  let meters = to_meters(value, from_unit);
  from_meters(meters, to_unit)
}

